//	DELETE FROM anime_config_candidates AS candidate
//	USING due
//	WHERE candidate.id = due.id
//	  AND candidate.cleanup_eligible_at IS NOT NULL
//	  AND candidate.cleanup_eligible_at <= CURRENT_TIMESTAMP
func (q *Queries) PurgeEligibleAnimeConfigCandidates(ctx context.Context, limit int32) (sql.Result, error) {
	return q.db.ExecContext(ctx, purgeEligibleAnimeConfigCandidates, limit)
}

const terminalizeOneShotAttempt = `-- name: TerminalizeOneShotAttempt :one
UPDATE one_shot_execution_attempts
SET state = $1,
    failed_stage = $2,
    outcome_code = $3,
    outcome_reason = $4,
    terminal_at = $5,
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = $6 AND state = 'running' AND version = $7
RETURNING version
`

type TerminalizeOneShotAttemptParams struct {
	State           string
	FailedStage     sql.NullString
	OutcomeCode     sql.NullString
	OutcomeReason   sql.NullString
	TerminalAt      sql.NullTime
	ID              string
	ExpectedVersion int64
}

// TerminalizeOneShotAttempt
//
//	UPDATE one_shot_execution_attempts
//	SET state = $1,
//	    failed_stage = $2,
//	    outcome_code = $3,
//	    outcome_reason = $4,
//	    terminal_at = $5,
//	    version = version + 1,
//	    updated_at = CURRENT_TIMESTAMP
//	WHERE id = $6 AND state = 'running' AND version = $7
//	RETURNING version
func (q *Queries) TerminalizeOneShotAttempt(ctx context.Context, arg TerminalizeOneShotAttemptParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, terminalizeOneShotAttempt,
		arg.State,
		arg.FailedStage,
		arg.OutcomeCode,
		arg.OutcomeReason,
		arg.TerminalAt,
		arg.ID,
		arg.ExpectedVersion,
	)
	var version int64
	err := row.Scan(&version)
	return version, err
}
